# ORIGINAL: F2's gate (R2 sprint, pl-prologflag.c push_prolog_flag, pop_prolog_flag, copy_prolog_flag, put_saved_flag_value) — push_prolog_flag/2 and
# pop_prolog_flag/1 against swipl 10.1.19; the rows are generated by evidence/F2/ (make_cases.py -> push_cases.json -> build_push_test.py -> this file;
# gen_push_rows.py pins swipl's answers).
# test/core_lang/test_push_flag_swipl.jl — the push stack of a flag: a flag that exists (a module flag, a Boolean flag of the mask, a flag of each
# type made by create_prolog_flag/3, a nest of three pushes, a set between push and pop), a flag that is ABSENT (created by the push, deleted by the
# pop, created again), the errors of the arguments and of `set_flag_value` on a push (the stack stays as it was), the FF_SHARED refusal, read-only,
# and `pop_prolog_flag` without a push (`existence_error(pushed_flag, K)`).
#   * A PROGRAM consulted by the kernel's loader, and cases `t_<id>(R)` run IN ORDER in one database, each wrapped in
#     `catch(Goal, error(E, _), R = raised(E))`; a case restores the flags it changes; a flag a case creates has the prefix zz_pf_ and later cases
#     read it (pf25 reads the flag of pf24, pf27 the float flag of pf26, pf33/pf34 the flag of pf32, pf36 the flag of pf35).
#   * Every answer line is swipl's, PINNED (swipl 10.1.19-1-gcbf4e189, evidence/F2/gen_push_rows.py, two runs byte-identical); with `swipl` on PATH
#     the live answers are compared with the pins too.
#   * A flag whose side effect is REFUSED BY NAME (F1b, design D4) stays refused on a push: the last testset (the kernel's answer alone: a swipl
#     push of `debug` would change the debugger).
# UNVERIFIED on the kernel: gate decides (every pin is swipl's; the rows were not run on the kernel).
using Test, LogicKernel
const LK = LogicKernel

# TERM TYPES PER CHUNK: REFERENCE — push_prolog_flag/2 and pop_prolog_flag/1 (src/os/pl-prologflag.jl), built on the term layer; every type in CI and at milestones
include(joinpath(@__DIR__, "..", "term_under_test.jl"))
const _PF = lk_term_type(Union{Int64, Float64, String, BigInt, Rational{BigInt}})
_pfs(x) = lk_sym(_PF, Symbol(x))

_pf_codes(s::String) = "[" * join(Int.(collect(s)), ",") * "]"
"A term as the driver's `enc/1` writes it: `V<i>` by first occurrence, atoms and functors by their codes."
function _pf_enc(t::_PF, seen::Vector{UInt64}=UInt64[])::String
    k = kind(t)
    if k === VAR
        i = findfirst(==(var_key(t)), seen)
        if i === nothing
            push!(seen, var_key(t))
            i = length(seen)
        end
        return "V$(i - 1)"
    elseif k === SYM
        return is_nil(t) ? "nil" : "a" * _pf_codes(sym_text(t))
    elseif k === GND
        v = lk_value(t)
        v isa AbstractString && return "s" * _pf_codes(String(v))
        v isa Integer && return "i$v"
        v isa Rational && return "q$(numerator(v))r$(denominator(v))"
        v isa AbstractFloat && return "f$(v)"
        return "?$(typeof(v))"
    end
    h = child(t, 1)
    return (is_nil(h) ? "c[]" : "c" * _pf_codes(sym_text(h))) * "/$(nchildren(t) - 1)(" *
           join([_pf_enc(child(t, i), seen) for i in 2:nchildren(t)], ",") * ")"
end

# the swipl side: the driver of test_at_body_swipl.jl (consult, then every answer of each t_<id>/1, `enc`oded)
const _PF_DRIVER = raw"""
enc(T) :- enc(T, [], _).
enc(V, S0, S) :- var(V), !, ( vidx(S0, V, 0, I) -> S = S0 ; length(S0, I), append(S0, [V], S) ), format("V~w", [I]).
enc(T, S, S) :- T == [], !, write(nil).
enc(T, S, S) :- atom(T), !, atom_codes(T, Cs), format("a~w", [Cs]).
enc(T, S, S) :- string(T), !, string_codes(T, Cs), format("s~w", [Cs]).
enc(T, S, S) :- integer(T), !, format("i~w", [T]).
enc(T, S, S) :- rational(T, N, D), !, format("q~wr~w", [N, D]).
enc(T, S, S) :- float(T), !, format("f~w", [T]).
enc(T, S0, S) :- compound_name_arity(T, N, A),
    ( N == [] -> write('c[]') ; atom_codes(N, Cs), format("c~w", [Cs]) ),
    format("/~w(", [A]), encargs(1, A, T, S0, S), write(')').
encargs(I, A, _, S, S) :- I > A, !.
encargs(I, A, T, S0, S) :- arg(I, T, X), enc(X, S0, S1), ( I < A -> write(',') ; true ),
    I1 is I+1, encargs(I1, A, T, S1, S).
vidx([X|_], V, I, I) :- X == V, !.
vidx([_|Xs], V, I0, I) :- I1 is I0+1, vidx(Xs, V, I1, I).
fz_pred(N) :-
    format("~w", [N]), functor(G, N, 1),
    catch(findnsols(50, G, G, Gs), _, Gs = [exception]),
    forall(member(S, Gs), ( S == exception -> write(' exception') ; write(' '), enc(S) )), nl.
fz_run(File, Ns) :-
    catch(( consult(File), S = ok ), E, S = exc(E)),
    ( S == ok -> writeln(ok) ; S = exc(B), write('exc '), enc(B), nl ),
    forall(member(N, Ns), fz_pred(N)).
"""
function _pf_swipl_lines(path::String, names::Vector{String})::Vector{String}
    out = mktempdir() do d
        f = joinpath(d, "drv.pl")
        write(
            f,
            _PF_DRIVER * ":- initialization((fz_run('$path', [" * join(names, ",") *
            "]), halt)).\n"
        )
        read(pipeline(`swipl -q $f`; stdin=devnull, stderr=devnull), String)
    end
    return String.(split(chomp(out), '\n'; keepempty=false))
end

# the program: none; the cases are the clauses (a comment line keeps the file a program)
const _PF_PROGRAM = raw"""
% the cases t_pfNN/1 follow
"""

# (id, goal), run IN ORDER
const _PF_CASES = [
@@CASES@@]

# swipl 10.1.19-1-gcbf4e189's answers to the program and cases above (the driver's lines; evidence/F2/push_rows.out)
const _PF_PINNED = [
# PINS-BEGIN
# PINS-END
]

"The program and cases as one file; the case predicates' names."
function _pf_file()::Tuple{String, Vector{String}}
    names = ["t_$(id)" for (id, _) in _PF_CASES]
    text =
        _PF_PROGRAM * join([
            "t_$(id)(R) :- catch(($g), error(SfE, _), R = raised(SfE)).\n" for
            (id, g) in _PF_CASES
        ])
    f = joinpath(mktempdir(), "pushflag.pl")
    write(f, text)
    return f, names
end

"The kernel's answers to the query `name(R)` in `gd`: the encoded lines, at most 50 answers; a Julia exception propagates."
function _pf_query(gd, ld, name::String)::String
    proc = LK.isCurrentProcedure(sym_key(_pfs(name)), 1, LK.MODULE_user(gd))
    if proc === nothing || !LK.isDefinedProcedure(gd, proc)
        return "$name undefined"
    end
    sols = String[]
    fid = LK.PL_open_foreign_frame(ld)
    a = LK.PL_new_term_refs(ld, 1)
    LK.putSlotValue!(ld, a + 1, mk_var(_PF, LK.fresh_var_keys!(1)), LK.PutVarMap())
    qid = LK.PL_open_query(
        gd, ld, nothing, LK.PL_Q_CATCH_EXCEPTION | LK.PL_Q_EXT_STATUS, proc, a
    )
    n = 0
    try
        while (n += 1) <= 50
            rc = LK.PL_next_solution(gd, ld, qid)
            if rc == LK.PL_S_TRUE || rc == LK.PL_S_LAST
                push!(
                    sols,
                    _pf_enc(mk_expr(_PF, _PF[_pfs(name), lk_answers(ld, (a:a)...)...]))
                )
                rc == LK.PL_S_LAST && break
            elseif rc == LK.PL_S_EXCEPTION
                push!(sols, "exception")
                break
            else
                break
            end
        end
    finally
        LK.PL_close_query(ld, qid)
        LK.PL_close_foreign_frame(ld, fid)
    end
    return "$name" * join(" " .* sols)
end

"The kernel's lines for `names` after consulting `path`, as the driver writes swipl's; the database and the local data."
function _pf_kernel(path::String, names::Vector{String})
    gd = LK.PL_global_data{_PF}()
    ld = LK.PL_local_data{_PF}(gd)
    st, ball, _ = LK.load_file!(gd, ld, path)
    out = [st === :ok ? "ok" : "exc " * _pf_enc(ball::_PF)]
    for name in names
        push!(out, _pf_query(gd, ld, name))
    end
    return out, gd, ld
end

@testset "set_prolog_flag/2, create_prolog_flag/3 and the flag side effects as swipl's (pf01-pf42)" begin
    f, names = _pf_file()
    kl, _, _ = _pf_kernel(f, names)
    @test length(kl) == length(_PF_PINNED)
    for (k, p) in zip(kl, _PF_PINNED)
        k == p || println(stderr, "  ours  ", k, "\n  swipl ", p)
        @test k == p
    end
    # not vacuous: the pins hold both kinds of answer — a raised error (permission, type, domain, instantiation) and a value read back
    raised = "c[114,97,105,115,101,100]"                 # raised(…)
    @test count(l -> occursin(raised, l), _PF_PINNED) >= 30
    @test count(l -> !occursin(raised, l) && startswith(l, "t_"), _PF_PINNED) >= 30
    @test any(l -> startswith(l, "t_pf01 ") && occursin("c[112,101,114,109,105,115,115,105,111,110,95,101,114,114,111,114]/3(", l), _PF_PINNED)
end

@testset "the pins are swipl's (live, when swipl is on PATH)" begin
    swipl = get(ENV, "LOGICKERNEL_NO_SWIPL", "") == "1" ? nothing : Sys.which("swipl")
    # the pinned table is the driver's whole output (the inert-testset guard: an assertion either way)
    @test length(_PF_PINNED) == length(_PF_CASES) + 1
    if swipl === nothing
        @info "F2 LIVE CHECK NOT RUN: `swipl` is not on PATH here. It runs in tools/run_tests.sh and CI."
    else
        f, names = _pf_file()
        @test _pf_swipl_lines(f, names) == _PF_PINNED
    end
end

# A push of a flag F1b refuses by name reaches `set_flag_value` and ends in `NotPortedError` (design D4); swipl itself would carry the side effect out,
# so these rows are the kernel's answer alone. The value is one swipl accepts, so the refusal is the answer, not a type error. After the refusal the
# stack is as it was: the flag has no pushed value, a pop raises existence_error (the kernel's answer, upstream's code: the new frame is only linked after
# `set_flag_value` succeeds).
const _PF_REFUSED = [
    ("debug", "true"), ("encoding", "utf8"), ("stack_limit", "1000000000"), ("autoload", "false"),
    ("agc_margin", "100"), ("var_tag", "dict"), ("heartbeat", "0")
]

@testset "push_prolog_flag of a flag refused by name raises NotPortedError (design D4)" begin
    text = join(
        [
            "r_$(f)(R) :- push_prolog_flag($f, $v), R = ok.\n" *
            "p_$(f)(R) :- catch(pop_prolog_flag($f), error(E, _), R = E).\n"
            for (f, v) in _PF_REFUSED
        ]
    )
    path = joinpath(mktempdir(), "refused.pl")
    write(path, text)
    for (f, _) in _PF_REFUSED
        gd = LK.PL_global_data{_PF}()
        ld = LK.PL_local_data{_PF}(gd)
        st, _, _ = LK.load_file!(gd, ld, path)
        @test st === :ok
        # UNVERIFIED on the kernel: gate decides (the refusal's class: the push reaches set_flag_value)
        @test_throws LK.NotPortedError _pf_query(gd, ld, "r_$(f)")
        # the flag was not left with a pushed value: pop raises existence_error(pushed_flag, F)
        line = _pf_query(gd, ld, "p_$(f)")
        @test occursin("c" * _pf_codes("existence_error") * "/2(a" * _pf_codes("pushed_flag") * ",a" * _pf_codes(f) * ")", line)
    end
    @test length(_PF_REFUSED) >= 7
end
